import type {
  HttpMethod,
  IsOperationRequestBodyOptional,
  PathsWithMethod,
  RequestBodyJSON,
  SuccessResponseJSON,
} from 'openapi-typescript-helpers';
import type { HttpContext, HttpHeaders } from '@angular/common/http';

export type { HttpMethod, PathsWithMethod, RequestBodyJSON, SuccessResponseJSON };

/**
 * Represents an OpenAPI paths record as generated by openapi-typescript.
 * Uses `{}` to match the same constraint used by openapi-typescript-helpers.
 */
// eslint-disable-next-line @typescript-eslint/ban-types
export type PathRecord = {};

/** Extract path parameters from an OpenAPI operation */
export type PathParameters<Op> = Op extends {
  parameters: { path?: infer P };
}
  ? NonNullable<P> extends Record<string, unknown>
    ? NonNullable<P>
    : never
  : never;

/** Extract query parameters from an OpenAPI operation */
export type QueryParameters<Op> = Op extends {
  parameters: { query?: infer Q };
}
  ? NonNullable<Q> extends Record<string, unknown>
    ? NonNullable<Q>
    : never
  : never;

/** Check if a type has required (non-optional) keys */
type HasRequiredKeys<T> = [T] extends [never]
  ? false
  : ({ [K in keyof T]-?: undefined extends T[K] ? never : K }[keyof T]) extends never
    ? false
    : true;

/** Conditionally adds a key to the object; makes it required if T has required keys */
type ParamEntry<K extends string, T> = [T] extends [never]
  ? // eslint-disable-next-line @typescript-eslint/ban-types
    {}
  : HasRequiredKeys<T> extends true
    ? { [P in K]: T }
    : { [P in K]?: T };

/** Combined path and query parameters for an OpenAPI operation */
export type OperationParameters<Op> = ParamEntry<'path', PathParameters<Op>> &
  ParamEntry<'query', QueryParameters<Op>>;

/** Request body type for an OpenAPI operation */
export type OperationBody<Op> = [RequestBodyJSON<Op>] extends [never]
  ? { body?: never }
  : IsOperationRequestBodyOptional<Op> extends true
    ? { body?: RequestBodyJSON<Op> }
    : { body: RequestBodyJSON<Op> };

/** Common HTTP request options */
export interface OpenApiRequestOptions {
  headers?: HttpHeaders | Record<string, string | ReadonlyArray<string>>;
  context?: HttpContext;
  withCredentials?: boolean;
}

/** Full typed request for an OpenAPI operation */
export type OpenApiOperationRequest<Op> = OperationParameters<Op> &
  OperationBody<Op> &
  OpenApiRequestOptions;
